Lemma od_byte_same d x : ltac2:(tb__ "0|2|
ScfSe7Vd;VdsF;A3SefVs;VL;Vsc;Vreq;Vrho;VbyM0;VbyA;VbyB;VbyC;VbyP;Vbnc;Vgd;Vmaskv;Vspanv;Vm0;Vd;A10S56SdbSbS5dS5dSe8Vs;VL;Vsc;Vm0;Vd;A5M0A3Vx;A2SdcVx;SdS5dS5dG0A3A2A2S56S55S6Sf6Q8A1A1S138Sd5S11bSf7Q40Vx;A2M1A3S138Sd5VmW;G1A3A3S55S7S139Sd5S11bG1A3S139Sd5VmW;G1A3A3A2F_;F_;F_;").
Proof using HI HMI HSF_match HSF_objs HagF Hbnc Hbnc_val Hbytes Hdepth HdsF_sem HdsF_vars Hent_hold Hgd Hhd Hm_ctz Hm_sct Hmaskv Hreq Hrom Hsc HsmF Hsp Hsp_high Hspanv.
  intros Hd Hok Hx. pose proof (od_range64 d) as R64.
  pose proof (HOF_d d Hd) as HO. pose proof (Hent_hold d Hd Hok) as HE.
  rewrite (rd_of_at segsU m' msF _ HromF (m'_in d x Hd Hx ltac:(lia))).
  destruct (od_rom d) as [l|] eqn:Er.
  -
    assert (RO : ro_addr segsU (Z_to_bv 64 x) = true).
    { destruct d; cbn [od_rom] in Er; try discriminate; cbn [od_range fst snd] in Hx.
      - replace x with (0x108cc + (x - 0x108cc)) by lia. apply ro_tables_P. lia.
      - replace x with (0x108cc + (x - 0x108cc)) by lia. apply ro_tables_P. lia. }
    pose proof (HroF _ RO) as N1.
    assert (N0 : mW (Z_to_bv 64 x) = None).
    { destruct d; cbn [od_rom] in Er; try discriminate; cbn [od_range fst snd] in Hx.
      - replace x with (0x108ec + (x - 0x108ec)) by lia. apply Hm_sct. lia.
      - replace x with (0x108cc + (x - 0x108cc)) by lia. apply Hm_ctz. lia. }
    split.
    + unfold rd, ms_read_byte, Glue.rd_of. rewrite N1, N0. rewrite HromF. reflexivity.
    + rewrite (wok_of_mem segsU m' mW); [reflexivity|]. rewrite (m'_in d x Hd Hx) by lia. rewrite N1, N0. reflexivity.
  - destruct (od_cover d x Er Hx) as (off & w & e & Hin & Hoff).
    pose proof (od_cell_bytes d rhoF msF off w e Hd HagF HO Hin (Z.to_nat (x - fst (od_range d) - off)) ltac:(lia)) as B1.
    pose proof (od_cell_bytes d rhoW (with_mem ms mW) off w e Hd (agrees_refl rhoW) HE Hin (Z.to_nat (x - fst (od_range d) - off)) ltac:(lia)) as B0.
    rewrite Z2Nat.id in B1, B0 by lia. replace (fst (od_range d) + off + (x - fst (od_range d) - off)) with x in B1, B0 by lia.
    rewrite (rd_with_mem segsU ms mW _ Hrom) in B0.
    split; [rewrite B1, B0; reflexivity|].
    destruct (dunk_byte segsU rhoF msF (obj_of d) x HO (od_dunk d Er) ltac:(rewrite (rngF d Hd); exact Hx)) as [_ W1].
    destruct (dunk_byte segsU rhoW (with_mem ms mW) (obj_of d) x HE (od_dunk d Er) ltac:(cbv delta [rhoW]; rewrite (od_rng d); exact Hx)) as [_ W0].
    rewrite (wok_of_at segsU m' msF _ (m'_in d x Hd Hx ltac:(lia)) W1). symmetry. apply wok_of_wview. exact W0.
Qed.

