Theorem VIN : ltac2:(tb__ "0|0|
S122ScfS122R1SfS122S123Vs';A1S166Vs';A1A3A3S11fR2A1S126VL;Vbv1;R3A3F_;F_;Fc;").
Proof using EmW Erd Ewok HI HI' HMI HSF_match HSF_objs HXr HXr' HagF Hbnc Hbnc_val Hbytes Hdelta Hdepth HdsC HdsF_ent HdsF_sem HdsF_vars Hent_hold Hgd Hhd Hm_ctz Hm_sct Hmaskv Hreq Hrom Hsc HsmF Hsp Hsp_high Hspanv bv0 rv0 rv1.
  intros c Hc (k & Hk & d & HdC & Rk). destruct (HdsC d HdC) as (Hd & Hok' & Hchg). pose proof Hctx as HCX.
  destruct d as [| | | |hv|x pv nv mv av fv bv|x yv|x yv]; try (destruct Hchg; fail); cbn [od_ok_at od_range fst snd] in Hok', Rk; cbn [od_chg_ok] in Hchg.
  -
    destruct Hok' as [Shv Ehv].
    assert (CM : cmeets L c (ly_ctx L + (CTX_active + 8 * sc)) 8) by (exists k; split; [exact Hk|]; rewrite HCX; unfold CTX_active; lia).
    pose proof (ctx_active_cell X R' U s' L HI' HXr' HL' c sc Hsc Hc CM) as ->.
    eapply (cell_from_od (OD_act hv) 0 8 hv _ (optrZ (active_hd s' sc))); [exact HdC | left; reflexivity | | reflexivity | | ].
    + cbn [mc_loc loc_addr od_range fst]. rewrite HCX. unfold CTX_active. lia.
    + cbn [cellZ mc_val]. rewrite optrZ_num. destruct (active_hd s' sc); reflexivity.
    + rewrite Ehv. reflexivity.
  -
    destruct Hok' as (S1 & S2 & S3 & S4 & S5 & S6 & am' & M' & E1 & E2 & E3 & E4 & E5 & E6).
    assert (CM : cmeets L c (addr_of L (mptr x)) META_SIZE) by (exists k; split; [exact Hk|]; unfold zA, META_SIZE in *; lia).
    pose proof (meta_zone X R' U s' L HI' HXr' HL' (mptr x) c ltac:(rewrite D_keys; apply mptr_key) Hc CM) as IN.
    rewrite M' in IN.
    assert (AG : forall dd, loc_addr L (LMem (padd (mptr x) dd)) = zA (mptr x) + 0 + dd) by (intros dd; unfold zA, addr_of, loc_addr; destruct (mptr x); cbn [padd]; lia).
    cbn in IN. unfold META_prev, META_next, META_mem, META_avail, META_freed, META_bits in IN.
    destruct IN as [<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]].
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 0 8 pv _ (optrZ (am_prev am'))); [exact HdC | cbn; tauto | apply AG | reflexivity | | rewrite E1; reflexivity].
      cbn [cellZ mc_val]. rewrite optrZ_num. destruct (am_prev am'); reflexivity.
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 8 8 nv _ (optrZ (am_next am'))); [exact HdC | cbn; tauto | apply AG | reflexivity | | rewrite E2; reflexivity].
      cbn [cellZ mc_val]. rewrite optrZ_num. destruct (am_next am'); reflexivity.
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 16 8 mv _ (zA (am_mem am'))); [exact HdC | cbn; tauto | apply AG | reflexivity | reflexivity | rewrite E3; reflexivity].
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 24 4 av _ (am_avail am')); [exact HdC | cbn; tauto | apply AG | reflexivity | reflexivity |].
      rewrite <- E4. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32). rewrite Z.mod_mod by lia. reflexivity.
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 28 4 fv _ (am_freed am')); [exact HdC | cbn; tauto | apply AG | reflexivity | reflexivity |].
      rewrite <- E5. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32). rewrite Z.mod_mod by lia. reflexivity.
    + eapply (cell_from_od (OD_meta x pv nv mv av fv bv) 32 8 bv _ (meta_bits am')); [exact HdC | cbn; tauto | apply AG | reflexivity | reflexivity | rewrite E6; reflexivity].
  -
    destruct Hok' as (S1 & am' & M' & Hy & Ea & Emem & Eml & Eex).
    assert (Hu' : usedX X s' (mptr x) am') by (unfold usedX, MTX; rewrite (proj2 (usedX_MT _ _ _ _ (proj1 (mam_used x)))); exact M').
    assert (CM : cmeets L c (addr_of L (am_mem am') + 8) 1) by (exists k; split; [exact Hk|]; rewrite Emem; unfold zA in *; lia).
    pose proof (aidx_zone X R' U s' L HI' HXr' HL' (mptr x) am' c Hu' Hc CM) as ->.
    pose proof (used_ranges X R' U s' HI' (mptr x) am' Hu') as (A1 & A2 & A3 & A4 & A5).
    assert (AG : loc_addr L (LMem (padd (am_mem am') 8)) = zA (am_mem (mam x)) + 8 + 0) by (rewrite Emem; unfold zA, addr_of, loc_addr; destruct (am_mem (mam x)); cbn [padd]; lia).
    unfold aidx_cell. rewrite Eml. destruct (am_maplen (mam x) =? 0) eqn:Em.
    + exact (cell5_from_od (OD_mem x yv) 0 yv _ (am_aidx am') HdC ltac:(left; reflexivity) AG Hy Ea).
    +
      apply Z.eqb_neq in Em. specialize (Eex ltac:(rewrite Eml; exact Em)).
      unfold cell_holds. cbn [mc_loc mc_w mc_val]. intros j Hj. rewrite AG.
      destruct j as [|j'].
      * pose proof (chg_byte (OD_mem x yv) 0 1 yv 0 HdC ltac:(left; reflexivity) ltac:(lia)) as B. cbn [od_range fst] in B.
        cbn [Z.of_nat]. rewrite B. f_equal.
        unfold le_byte. change (2 ^ (8 * Z.of_nat 1)) with 256. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32). change (8 * 0) with 0. rewrite !Z.shiftr_0_r.
        cbn [sval_num]. rewrite Eex. rewrite !Z.mod_small; lia.
      *
        assert (NT : ~ touched (zA (am_mem (mam x)) + 8 + 0 + Z.of_nat (S j'))).
        { intros (d' & Hd'C & RR0). destruct (HdsC d' Hd'C) as (Hd' & Hok2 & Hchg2). pose proof (mem_zone x) as ZX.
          destruct d' as [| | | |hv2|x2 p2 n2 q2 a2 f2 b2|x2 y2|x2 y2]; try (destruct Hchg2; fail); cbn [od_range fst snd] in RR0.
          - unfold zA in *. lia.
          - pose proof (meta_vs_group X None U s L HI HL (mptr x2) (mptr x) (mam x) (8 + Z.of_nat (S j')) (mptr_key x2) (proj1 (mam_used x))) as D.
            pose proof (inv_groups HI _ _ (proj1 (mam_used x))) as G. pose proof (stride_pos _ _ _ _ _ G) as Sp. pose proof G as ((Glast & _) & _).
            assert (E28 : 28 <= group_extent (mam x)) by (unfold group_extent; assert (stride_of (mam x) <= stride_of (mam x) * (am_last (mam x) + 1)) by nia; unfold UNIT, IB; lia).
            specialize (D ltac:(unfold IB; lia)). unfold zA, META_SIZE in *. lia.
          -
            pose proof (mem_R x2) as R2. pose proof (mem_R x) as R1. unfold zA in *. lia.
          - unfold zA in *. lia. }
        eassert (XX : _); [|destruct (V1 _ XX NT) as [E _]]. { pose proof (mem_zone x). top_ranges. unfold zA in *. assert (Z.of_nat (S j') < 4) by lia. lia. }
        rewrite E.

        pose proof (aidx_cell_In X None U s HI HXr (mptr x) (mam x) (proj1 (mam_used x))) as CI.
        unfold aidx_cell in CI. rewrite (proj2 (Z.eqb_neq _ _) Em) in CI.
        pose proof (proj1 (Forall_forall _ _) (proj1 (proj2 (proj1 HreprO))) _ CI) as CH.
        unfold MallocInv.cell_holds in CH. cbn [mc_loc mc_w mc_val] in CH.
        specialize (CH (S j') Hj). unfold bv0 in CH.
        replace (loc_addr L (LMem (padd (am_mem (mam x)) 8))) with (zA (am_mem (mam x)) + 8 + 0) in CH
          by (unfold zA, addr_of, loc_addr; destruct (am_mem (mam x)); cbn [padd]; lia).
        unfold bv0. rewrite CH. f_equal. cbn [sval_num]. pose proof (mem_R x) as RX.
        unfold le_byte. change (2 ^ (8 * Z.of_nat 4)) with (2 ^ 32). rewrite !(Z.mod_small _ (2 ^ 32)) by lia.
        rewrite !Z.shiftr_div_pow2 by lia.
        assert (P : 256 <= 2 ^ (8 * Z.of_nat (S j'))).
        { change 256 with (2 ^ 8). apply Z.pow_le_mono_r; lia. }
        rewrite (Z.div_small (am_aidx (mam x))) by lia. rewrite (Z.div_small (am_aidx am')) by lia. reflexivity.
  -
    destruct Hok' as (S1 & Hy & Eb). specialize (Eb Hchg).
    assert (CM : cmeets L c (ly_ctx L + (CTX_bounces + (sc - 7))) 1) by (exists k; split; [exact Hk|]; rewrite HCX; unfold CTX_bounces; lia).
    pose proof (ctx_bounce_cell X R' U s' L HI' HXr' HL' c (sc - 7) ltac:(lia) Hc CM) as ->.
    eapply (cell_from_od (OD_bnc x yv) 0 1 yv _ (nth (Z.to_nat (sc - 7)) (st_bounces s') 0)); [exact HdC | left; reflexivity | | reflexivity | reflexivity |].
    + cbn [mc_loc loc_addr od_range fst]. rewrite HCX. unfold CTX_bounces. lia.
    + rewrite Eb. unfold znth. reflexivity.
Qed.

