Proof using EmW HI HMI HXr HagF Hbnc Hbnc_val Hbytes Hdepth HdsF_vars Hgd Hhd Hm_ctz Hm_sct Hmaskv Hreq Hsc HsmF Hsp Hspanv. try clear Hsp_high.
  intros a Ha NO NO' NE NS.
  destruct (in_ranges_dec rhoF NREL (Z_to_bv 64 a)) as [IN|OUT]; [| exact (m'_out a Ha ltac:(intros d Hd R; apply OUT; apply (in_NREL a Ha); exists d; auto))].
  apply (in_NREL a Ha) in IN as (d & Hd & R). pose proof Hctx as HCX.
  assert (OWN : alloc_owned L s a -> False) by (intros H; apply NO; unfold ma_owned, owned; cbn [ma_s ma_L]; left; exact H).
  destruct d as [| | | |hv|x pv nv mv av fv bv|x yv|x yv]; cbn [od_range fst snd] in R.
  - exfalso. apply NS. unfold alloc_static. cbn. right; left. lia.
  - exfalso. apply NS. unfold alloc_static. cbn. right; right. lia.
  -
    rewrite (m'_in OD_sct a Hd R Ha). rewrite (HroF (Z_to_bv 64 a)) by (replace a with (0x108cc + (a - 0x108cc)) by lia; apply ro_tables_P; lia).
    rewrite <- EmW. symmetry. replace a with (0x108ec + (a - 0x108ec)) by lia. apply Hm_sct. lia.
  - rewrite (m'_in OD_ctz a Hd R Ha). rewrite (HroF (Z_to_bv 64 a)) by (replace a with (0x108cc + (a - 0x108cc)) by lia; apply ro_tables_P; lia).
    rewrite <- EmW. symmetry. replace a with (0x108cc + (a - 0x108cc)) by lia. apply Hm_ctz. lia.
  - exfalso. apply OWN. replace a with (ly_ctx L + (a - ly_ctx L)) by lia. apply ctx_owned. rewrite HCX. unfold CTX_SIZE. lia.
  - exfalso. apply OWN.

    destruct (mam_used x) as (_ & _ & M).
    assert (C : forall off (w : nat) vv, In (MCell (LMem (padd (mptr x) off)) w vv) (meta_slot_cells (mptr x) (MT s (mptr x))) ->
              zA (mptr x) + off <= a < zA (mptr x) + off + Z.of_nat w -> alloc_owned L s a).
    { intros off w vv Hin Hx.
      pose proof (image_cell_owned X None U s L HI HXr HL _ (meta_cells_in_imageI X None U s HI (mptr x) _ (mptr_key x) Hin) (Z.to_nat (a - (zA (mptr x) + off))) ltac:(cbn [mc_w]; lia)) as OW.
      cbn [mc_loc] in OW. replace (loc_addr L (LMem (padd (mptr x) off)) + Z.of_nat (Z.to_nat (a - (zA (mptr x) + off)))) with a in OW; [exact OW|].
      unfold zA, addr_of, loc_addr. destruct (mptr x); cbn [padd]. unfold zA, addr_of, loc_addr in Hx. cbn in Hx. lia. }
    rewrite M in C. cbn [meta_slot_cells] in C. unfold META_prev, META_next, META_mem, META_avail, META_freed, META_bits in C.
    destruct (Z_lt_dec a (zA (mptr x) + 8)); [eapply (C 0 8%nat); [cbn; tauto | change (Z.of_nat 8%nat) with 8; lia]|].
    destruct (Z_lt_dec a (zA (mptr x) + 16)); [eapply (C 8 8%nat); [cbn; tauto | change (Z.of_nat 8%nat) with 8; lia]|].
    destruct (Z_lt_dec a (zA (mptr x) + 24)); [eapply (C 16 8%nat); [cbn; tauto | change (Z.of_nat 8%nat) with 8; lia]|].
    destruct (Z_lt_dec a (zA (mptr x) + 28)); [eapply (C 24 4%nat); [cbn; tauto | change (Z.of_nat 4%nat) with 4; lia]|].
    destruct (Z_lt_dec a (zA (mptr x) + 32)); [eapply (C 28 4%nat); [cbn; tauto | change (Z.of_nat 4%nat) with 4; lia]|].
    eapply (C 32 8%nat); [cbn; tauto | change (Z.of_nat 8%nat) with 8; lia].
  - exfalso. apply OWN. replace a with (zA (am_mem (mam x)) + 8) by lia. apply aidx_owned.
  - exfalso. apply OWN. replace a with (ly_ctx L + (a - ly_ctx L)) by lia. apply ctx_owned. rewrite HCX. unfold CTX_SIZE. lia.
Qed.

